# Gaston Deschênes, Un pays rebelle. La Côte-du-Sud et la guerre de l'Indépendance américaine, Québec, Septentrion, 2023.
# PDF du Drive de l'auteur (HISTOIRE_LIVRES/GUERRE_INDENDANCE_USA_QUEBEC), lu en entier dans la visionneuse du Drive (291 p. ;
# le texte extrait par le Drive s'arrêtait au premier tiers). Pagination : pages de la visionneuse. Corpus « Recherches », préfixe DS23.
from commun import Corpus
DS = "Deschênes, Gaston (2023), Un pays rebelle. La Côte-du-Sud et la guerre de l'Indépendance américaine, Québec, Septentrion"
C = Corpus('Recherches', 'DS23', DS, page_fmt='p. {}')
F = C.F
F('01', "Pointe-Lévy : le camp d'Arnold et les recrues de Pierre Ayotte et Clément Gosselin (hiver 1775-1776)", 'evenement', '1775-11-08/1776-04', -71.170, 46.810, 'c', ['Benedict Arnold', 'Pierre Ayotte', 'Clément Gosselin', 'Germain Dionne', 'Moses Hazen', 'James Livingston'],
  "Arrivé à Pointe-Lévy le 8 novembre 1775 avec 650 des 1 000 hommes partis par la Kennebec et la Chaudière, Arnold y maintient son camp tout l'hiver. Les habitants de la Côte-du-Sud bloquent les vivres destinés à Québec et ravitaillent les assiégeants. Pierre Ayotte, de Kamouraska, et Clément Gosselin, de Sainte-Anne, avec le beau-père de ce dernier, Germain Dionne, recrutent environ 130 Canadiens pour le Congrès (40 livres de gratification, puis 40 livres par mois) : le journal de Baby en nomme 95, dont la moitié de Sainte-Anne, de Rivière-Ouelle et de Kamouraska, soit environ le quart des Canadiens des régiments de Livingston et de Hazen.", '60-90')
F('02', "Saint-Pierre-du-Sud : la bataille entre Canadiens royalistes et rebelles (25 mars 1776)", 'evenement', '1776-03-25', -70.580, 46.895, 'c', ['Louis Liénard de Beaujeu de Villemonde', 'Charles-François Bailly de Messein', 'Michel-Toussaint Blais', 'Clément Gosselin', 'Pierre Ayotte', 'Lewis Dubois'],
  "Mandaté par Carleton, Louis Liénard de Beaujeu lève des volontaires jusqu'à Kamouraska ; son avant-garde d'une cinquantaine d'hommes, avec l'abbé Bailly de Messein, est attaquée le 25 mars 1776 chez le capitaine et coseigneur Michel-Toussaint Blais par 80 soldats du major Lewis Dubois et plus de 120 Canadiens rebelles recrutés par Gosselin et Ayotte. Les royalistes sont mis en déroute : au moins trois morts (Joseph et Germain Morin, de Saint-Roch, et un jeune homme de Saint-Thomas), une dizaine de blessés, dont Bailly de Messein, atteint de deux balles, et trente-huit prisonniers. Le lendemain, Marie-Françoise Harnois aurait été baptisée sous la garde de soldats bostonnais.", '81-106')
F('03', "Bristol (Pennsylvanie) : mort en captivité du seigneur de Berthier, Rigauville (30 oct. 1776)", 'evenement', '1776-10-30', -74.852, 40.100, 'c', ['Rigauville'],
  "Surpris ivre à la tête de son détachement près de Contrecœur à l'automne 1775, le seigneur de Rigauville, coseigneur de Berthier sur la Côte-du-Sud, est fait prisonnier par les Bostonnais, emmené aux États-Unis et meurt à Bristol (Pennsylvanie) le 30 octobre 1776. Son frère Charles-Régis, chanoine et supérieur de l'Hôpital général de Québec occupé par les Américains, dernier des Rigauville au Canada, meurt en 1780.", '42-43')
F('04', "Hartford (Connecticut) : les royalistes de Saint-Pierre envoyés en captivité (juin 1776)", 'evenement', '1776-06-25', -72.685, 41.764, 'c', ['Augustin Lauzier', 'François Pelletier'],
  "La « liste des personnes capturées au Canada et envoyées à Hartford, au Connecticut », dressée à Albany le 25 juin 1776, nomme cinq miliciens « pris au combat à Saint-Pierre » : Augustin Lauzier père et fils, Jean Isabelle, François et Louis Pelletier. D'autres Canadiens passent par Albany, Hartford et New York, où un échange de 1778 envoie 76 d'entre eux couper du bois à Long Island.", '100-110', "Pagination approximative.")
F('05', "Yorktown : le capitaine Clément Gosselin blessé avec le régiment de Hazen (oct. 1781)", 'evenement', '1781-10-11/1781-10-19', -76.510, 37.239, 'c', ['Clément Gosselin', 'Louis Gosselin', 'Germain Dionne', 'Moses Hazen', 'Charles Cloutier'],
  "Né à Sainte-Famille (île d'Orléans) en 1747, menuisier et charpentier d'églises à Sainte-Anne, Cap-Saint-Ignace, Saint-Roch et Kamouraska, Clément Gosselin devient capitaine du 2e régiment canadien de Moses Hazen (« Congress' Own »), mène pour Washington des missions d'espionnage au Canada (1778-1780) et commande une compagnie canadienne. Le régiment hiverne à Fishkill (1780-1781), passe à Albany et West Point, puis prend part au siège de Yorktown, où Gosselin est blessé entre le 11 et le 14 octobre 1781. Promu major à sa libération (juin 1783), il est admis avec son frère Louis et Germain Dionne à la Société des Cincinnati.", '118-139')
F('06', "Fishkill (New York) : le camp des réfugiés canadiens et la pétition de Gosselin au Congrès (1783-1786)", 'migration', '1783-06/1786-08', -73.899, 41.535, 'c', ['Clément Gosselin', 'Pierre Ayotte', 'Moses Hazen', 'James Livingston', 'George Clinton'],
  "Sans biens rendus par le traité de Paris ni État de rattachement, les anciens soldats canadiens et leurs familles vivent des rations du Congrès dans un camp à Fishkill. Une pétition présentée par Clément Gosselin au nom de quatre-vingts hommes et femmes, sans compter les enfants, obtient la résolution du 9 août 1783 recommandant à l'État de New York de les recevoir comme citoyens et de leur accorder des terres ; les rations sont prolongées jusqu'en septembre 1787. Les officiers rappellent en 1784 qu'ils ont levé deux compagnies à leurs frais à Albany en 1776 et sont « résolus à ne plus jamais vivre sous le gouvernement britannique ».", '139-146')
F('07', "Pointe-aux-Roches (« Hazenbourg », Beekmantown) : la Canadian and Nova Scotia Refugee Tract (1783-1816)", 'etablissement', '1783-08-10/1816-03-09', -73.400, 44.770, 'c', ['Clément Gosselin', 'Benjamin Mooers', 'Charles Cloutier', 'Michel Arbour', 'Jean Laframboise'],
  "Le 10 août 1783, Benjamin Mooers, ancien adjudant de Hazen, débarque avec un groupe de Canadiens à Pointe-aux-Roches, que l'on appellera « Hazenbourg ». La loi new-yorkaise de mai 1784 accorde aux réfugiés du Canada et de la Nouvelle-Écosse des lots de 80 et de 420 acres à l'ouest du lac Champlain (1 000 acres aux officiers, 500 aux soldats) ; en août 1786, les réfugiés quittent Fishkill pour le tirage au sort, et le recensement du 11 août 1787 compte 169 personnes au lac Champlain. Gosselin vend ses 1 000 acres en 1789 pour soixante livres et meurt à Beekmantown, sans doute à Pointe-aux-Roches, le 9 mars 1816.", '150-162')
F('08', "Rivière Chazy : le major Gosselin, « autrefois Canadien et maintenant Américain », et ses descendants (1787-1891)", 'famille', '1787/1891-02-28', -73.440, 44.890, 'c', ['Clément Gosselin', 'Marie-Charlotte Ouimet', 'Catherine Monty', 'Murdoch McPherson', 'Jane Gosselin Monty', 'Lewis Monty'],
  "Veuf de Marie Dionne, Gosselin épouse à Longueuil en 1787 Marie-Charlotte Ouimet ; le notaire le dit « major dans les armées des États-Unis et chevalier de l'Ordre de Saint-Cinaty, demeurant au lac Champlain à Hazinbourg », et le vicaire général le dit « olim canadensem et nunc americanum ». Le couple vit le long de la rivière Chazy, d'où Gosselin écrit à Washington le 18 septembre 1789. Il se remarie à l'automne 1790 à Chazy, devant le juge de paix Murdoch McPherson, avec Catherine Monty, fille d'un compagnon d'armes, puis s'établit au Canada. Sa veuve meurt à Chazy chez sa fille Jane en 1840 ; Jane (Marie-Geneviève) y meurt en 1891 des suites d'un vol à domicile.", '155-163')
F('09', "Champlain (New York) : Pierre Ayotte et Louis Gosselin, vétérans canadiens de la Révolution (1785-1823)", 'personnage', '1735-04-06/1882', -73.443, 44.986, 'c', ['Pierre Ayotte', 'Louis Gosselin', 'Francis Picard', 'Warner Miller'],
  "Né à Kamouraska en 1735, Pierre Ayotte se dit en 1785 marchand de fourrures chez les Indiens du sud-ouest depuis vingt ans ; un Pierre Ayotte paraît en 1770 comme « trader of Fort Vicienne » (Vincennes) et négociant à Détroit. Capitaine pour le Congrès en 1775-1776, réfugié à Albany puis au lac Champlain, il est recensé à Champlain en 1790 et y meurt le 15 octobre 1814 ; les demandes de ses héritiers devant la Cour des réclamations et le Congrès (projets de loi de 1858, 1860 et 1882) restent sans suite. Louis Gosselin, frère de Clément, recensé à Champlain en 1790, y aurait bâti la première maison de pierre ; maçon infirme, il obtient sa pension en 1819-1820 et meurt en 1823.", '161-189')
F('10', "Saratoga : Amédée Papineau rencontre le vieux rebelle Charles Cloutier (3 avril 1840)", 'rencontre', '1840-04-03', -73.760, 43.060, 'a', ['Charles Cloutier', 'Amédée Papineau', 'Clément Gosselin'],
  "Exilé à Saratoga avec son père après la rébellion de 1837-1838, Amédée Papineau rencontre le 3 avril 1840 Charles Cloutier, « une relique de la Révolution » de 87 ans, de la paroisse de Saint-Pierre : engagé en 1775 avec les Américains sous le capitaine Gosselin, il a suivi l'armée jusqu'à Albany, reçu une terre dans la Refugee Tract, puis s'est fixé à l'est du lac Saratoga, où il a épousé une Américaine. Il parle encore français, porte à pied un sac de farine sur son dos et touche une petite pension ; il déclarait en 1818 avoir servi à Québec, White Plains, Elizabethtown et Yorktown. Il est recensé à Saratoga en 1841.", '228-230', "Point placé à l'est du lac Saratoga.")
F('11', "Trombly Bay (comté de Clinton) : les frères Julien et Noël Bélanger, fils du seigneur de L'Islet, réfugiés au lac Champlain", 'famille', '1776/1842-09-20', -73.420, 44.790, 'a', ['Julien Bélanger', 'Noël Bélanger', 'Margaret Vigeant', 'Marie-Ursule Boileau'],
  "Fils de Jean-François Bélanger dit Bonsecours, seigneur de L'Islet, Julien et Noël Bélanger s'engagent avec les Bostonnais dès 1775-1776, puis dans le régiment de Hazen jusqu'en 1783 ; Noël aurait fait trois missions d'espionnage avec Gosselin. Réfugiés à Albany en 1784 puis au lac Champlain en 1787, ils cèdent leurs lots en 1789 ; Julien, journalier à Pointe-aux-Roches en 1801, « farmer » en 1820, épouse Marguerite Vigeant, dont la stèle (morte en 1842) se dresse au cimetière catholique de Trombly Bay.", '199-204', "Emplacement approximatif près de Pointe-aux-Roches.")
fiches = C.fiches
